const blocks = $input.all();
const userMsg = $('When Executed by Another Workflow').first().json.message_text || '';
const shortMem = $('When Executed by Another Workflow').first().json.short_memory || '';

// Extract all text content from blocks
let fullText = '';
for (const item of blocks) {
  const block = item.json;
  const type = block.type;
  if (!block[type]) continue;

  const richText = block[type].rich_text || block[type].text || [];
  for (const t of richText) {
    const content = t.plain_text || t.text?.content || '';
    if (content) fullText += content + '\n';
  }
}

// Simple keyword-based relevance: extract sections most relevant to query
const searchTerms = userMsg.toLowerCase().split(/\s+/).filter(w => w.length > 2);
const lines = fullText.split('\n').filter(l => l.trim());

let relevantLines = [];
for (const line of lines) {
  const lineLower = line.toLowerCase();
  for (const term of searchTerms) {
    if (lineLower.includes(term)) {
      relevantLines.push(line);
      break;
    }
  }
}

// If no keyword match, provide full KB context (it's small enough in Sprint 1)
let kb_context = '';
let kb_hit = false;

if (relevantLines.length > 0) {
  kb_context = relevantLines.join('\n').substring(0, 2000);
  kb_hit = true;
} else {
  // Fall back to full KB (small enough for Sprint 1)
  kb_context = fullText.substring(0, 2000);
  kb_hit = fullText.trim().length > 0;
}

return [{ json: { kb_hit, kb_context } }];
